pragma solidity >=0.8.0;

contract EnvProbe {
    uint256 public numberSeen;
    uint256 public timeSeen;
    address public lastBy;

    event Snapshot(uint256 number, uint256 timestamp, uint256 senderId);

    function snapshot() public {
        uint256 n = block.number;
        numberSeen = n;
        timeSeen = block.timestamp;
        lastBy = msg.sender;
        emit Snapshot(n, block.timestamp, uint256(uint160(msg.sender)));
    }

    function getNumber() public view returns (uint256) {
        return block.number;
    }

    function getTime() public view returns (uint256) {
        return block.timestamp;
    }

    function nextNumber() public view returns (uint256) {
        return block.number + 1;
    }

    function lastById() public view returns (uint256) {
        return uint256(uint160(lastBy));
    }
}
